void Solver::bump_var(int var, double coeff) {
    if (coeff == 0.0) return;                         // nothing to do
    // Compute increment once
    double inc = var_inc * coeff;
    double new_act = activity[var] + inc;

    // Lazy overflow protection: rescale only when activity exceeds a high bound
    const double OVERFLOW_LIMIT = 1e120;               // larger than original 1e100
    if (new_act > OVERFLOW_LIMIT) {
        const double SCALE = 1e-120;
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
        new_act = activity[var] + inc;                 // recompute after scaling
    }
    activity[var] = new_act;

    // Keep the VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) {
        vsids.update(var);
    } else {
        // If the variable was removed from the heap (e.g., after backtrack), re‑insert it.
        vsids.insert(var);
    }
}
